 const atras=L.filter(t=>t.venc<hoje()),aIn=atras.filter(t=>t.tipo==='rec').reduce((a,t)=>a+t.valor,0),aOut=atras.filter(t=>t.tipo==='pag').reduce((a,t)=>a+t.valor,0);
 for(let i=0;i<n;i++){const a=sem?addD(hoje(),7*i):(i?addM(hoje().slice(0,8)+'01',i):hoje()),b=sem?addD(hoje(),7*i+6):addD(addM(hoje().slice(0,8)+'01',i+1),-1),it=L.filter(t=>t.venc>=a&&t.venc<=b),ent=it.filter(t=>t.tipo==='rec').reduce((x,t)=>x+t.valor,0)+(i?0:aIn),sai=it.filter(t=>t.tipo==='pag').reduce((x,t)=>x+t.valor,0)+(i?0:aOut),ini=s;s+=ent-sai;rows.push({a,b,ini,ent,sai,fim:s,n:it.length+(i?0:atras.length)});}
