function T_config(){const c=FN.cfg,f=(k,l,v,o={})=>'<label class="ob-field'+(o.wide?' cad-wide':'')+'"><span>'+l+'</span>'+(o.html||'<input data-fn-cfg="'+k+'" type="'+(o.type||'text')+'" value="'+esc(v)+'"'+(o.ph?' placeholder="'+esc(o.ph)+'"':'')+'>')+(o.hint?'<small>'+o.hint+'</small>':'')+'</label>';
 return '<div class="cad-two">'+panel('Contas bancárias','Saldo de partida do fluxo de caixa. As baixas registradas depois da data do saldo atualizam o caixa.','<div class="table-wrap"><table class="ob-t"><thead><tr><th>Conta</th><th class="ob-n">Saldo</th><th>Data do saldo</th><th></th></tr></thead><tbody>'+(FN.contas.map(a=>'<tr><td><input class="fn-in-t" data-fn-ct="'+a.id+'" data-k="nome" value="'+esc(a.nome)+'" aria-label="Nome da conta"></td><td class="ob-n"><input class="ob-pct fn-money" data-fn-ct="'+a.id+'" data-k="saldo" value="'+nf(a.saldo)+'" aria-label="Saldo"></td><td><input type="date" class="ob-date" data-fn-ct="'+a.id+'" data-k="data" value="'+a.data+'"></td><td><button class="text-button" data-fn-ctdel="'+a.id+'">Excluir</button></td></tr>').join('')||'<tr><td colspan="4">Nenhuma conta. Cadastre a primeira.</td></tr>')+'</tbody></table></div><div class="ob-actions"><button class="button primary" id="fn-ctadd">+ Conta bancária</button></div><p class="ob-big"><span>Saldo atual</span><strong>'+BRL(saldoAtual())+'</strong></p>')+
 panel('Emitente das notas fiscais','Dados da Armant usados no XML','<div class="ob-form">'+f('razao','Razão social',c.razao,{wide:1})+f('cnpj','CNPJ',c.cnpj,{ph:'00.000.000/0000-00'})+f('im','Inscrição municipal',c.im)+f('ie','Inscrição estadual',c.ie)+f('mun','Município',c.mun)+f('cMun','Código IBGE do município',c.cMun,{hint:'Porto Alegre: 4314902'})+f('uf','UF',c.uf)+
 f('regime','Regime tributário','',{html:'<select data-fn-cfg="regime">'+[['1','Simples Nacional'],['2','Simples Nacional · excesso de sublimite'],['3','Regime normal (lucro presumido ou real)']].map(([v,l])=>'<option value="'+v+'"'+(c.regime===v?' selected':'')+'>'+l+'</option>').join('')+'</select>'})+f('cServ','Código de serviço padrão',c.cServ)+f('aliqISS','Alíquota ISS padrão (%)',c.aliqISS,{type:'number'})+f('serieNFSe','Série NFS-e',c.serieNFSe)+f('serieNFe','Série NF-e',c.serieNFe)+f('prazoPag','Prazo padrão de pagamento de compras (dias)',c.prazoPag,{type:'number'})+'</div><p class="area-note">Salvo ao digitar. Confirme tudo com a contabilidade antes de usar os XML.</p>')+'</div>';}

